sum-to:
def sum_to(n):
    total = 0
    for number in range(1, n + 1):
        total += number
    return total

find-max:
def find_max(numbers):
    best = numbers[0]
    for number in numbers:
        if number > best:
            best = number
    return best

drop-negatives:
def drop_negatives(numbers):
    kept = []
    for number in numbers:
        if number >= 0:
            kept.append(number)
    return kept

total-price:
def total_price(prices):
    total = 0
    for price in prices:
        total += price
    return total
